  const nbaSecs = [['picks', 'Best 5 today'], ['matchups', 'Matchups'], ['dvp', 'Defense vs Position'], ['research', 'Player Research Center'], ['news', 'Injuries & news'], ['bank', 'Bankroll'], ['record', 'Pick record' + (rec ? ' · ' + rec : '')], ['all', 'All 100 players']];
